<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Чем бюджетные ассигнования отличаются от лимитов бюджетных обязательств?", "acceptedAnswer": {"@type": "Answer", "text": "Ассигнования — предельные объёмы средств, заложенные в бюджете и сводной росписи на год под расходы; лимиты — доведённый до конкретного учреждения объём прав принимать и исполнять обязательства в текущем году. Ассигнования принадлежат бюджету, лимиты — учреждению; контракты заключаются в пределах лимитов, а не ассигнований."}}, {"@type": "Question", "name": "Что такое выделенный лимит простыми словами?", "acceptedAnswer": {"@type": "Answer", "text": "Это доведённые до заказчика лимиты бюджетных обязательств по нужному коду классификации — «сколько ему разрешили наобещать и заплатить в этом году». Это право, а не сумма на счёте."}}, {"@type": "Question", "name": "Чем бюджетное обязательство отличается от денежного?", "acceptedAnswer": {"@type": "Answer", "text": "Бюджетное обязательство возникает при заключении контракта и ставится на учёт в казначействе; денежное — когда подрядчик сдал этап и заказчик принял акт, то есть появилась обязанность заплатить конкретную сумму. Санкционируется к оплате именно денежное обязательство."}}, {"@type": "Question", "name": "Может ли заказчик заключить контракт без доведённых лимитов?", "acceptedAnswer": {"@type": "Answer", "text": "Нет: государственные и муниципальные контракты заключаются и оплачиваются в пределах лимитов бюджетных обязательств (статья 72 БК), а получатель бюджетных средств принимает обязательства только в пределах доведённых ему лимитов (статья 219 БК). Поэтому заключённый контракт подтверждает, что лимиты были."}}, {"@type": "Question", "name": "Что происходит с контрактом при уменьшении лимитов?", "acceptedAnswer": {"@type": "Answer", "text": "По пункту 6 статьи 161 БК казённое учреждение обязано согласовать с подрядчиком новые условия по цене, количеству и срокам; подрядчик вправе требовать возмещения фактически понесённого ущерба. Автоматически контракт не прекращается и обязанность оплатить принятое исполнение не исчезает."}}, {"@type": "Question", "name": "Как лимиты связаны с казначейским сопровождением?", "acceptedAnswer": {"@type": "Answer", "text": "Никак напрямую: лимиты и ассигнования — понятия заказчика. У подрядчика под сопровождением свой контур — целевые средства на лицевом счёте и санкционирование каждого списания по Сведениям об операциях. Отказ в санкционировании у исполнителя не связан с лимитами заказчика."}}, {"@type": "Question", "name": "Является ли «нет лимитов» основанием не платить по контракту?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Срок оплаты по закону № 44-ФЗ считается от приёмки и не зависит от доведения лимитов; недоведение лимитов — внутренняя проблема бюджетной вертикали. Подробный порядок действий — в статье о лимитах и оплате контракта."}}]}
</script>
